import { Automaton, AutomatonRunner, Tape } from "retiam/graphs";
const machine = new Automaton();
machine.addState("even", { isStart: true, isAccepting: true, label: "even" });
machine.addState("odd", { label: "odd" });
machine.addTransition("even", "even", "0");
machine.addTransition("odd", "odd", "0");
machine.addTransition("even", "odd", "1");
machine.addTransition("odd", "even", "1");
machine.getNode("even")!.move([-2, 0, 0]);
machine.getNode("odd")!.move([2, 0, 0]);
this.add(machine);
const result = machine.trace("1010"); // accepted: true
console.log(result.states, result.steps, result.accepted);
const tape = new Tape({ symbols: "1010" }).move([0, -2.5, 0]);
const runner = new AutomatonRunner(machine, tape);
this.add(tape, runner);
await runner.run(this, "1010", 0.65);
